async (page) => {
  const results = {};
  await page.goto('http://localhost:3002');
  results.titleRoster = await page.evaluate(() => { try { return eval('featuredRoster'); } catch (error) { return String(error); } });
  results.touchButtons = await page.locator('.touch-btn').evaluateAll(buttons => buttons.map(button => button.getAttribute('aria-label')));
  results.buildProfiles = await page.evaluate(() => {
    try { return eval("['Jax','Scorpion','Dhalsim'].map(name => ({name, build:fighterBuilds[name]}))"); }
    catch (error) { return String(error); }
  });
  for (const [first, second] of [['Jax','Scorpion'], ['Dhalsim','Raiden']]) {
    await page.evaluate(([a,b]) => eval(`p1.name='${a}'; p2.name='${b}'`), [first, second]);
    await page.waitForTimeout(100);
    await page.screenshot({ path: `/tmp/opencode/rift-${first.toLowerCase()}-${second.toLowerCase()}.png` });
    results[`visual-${first}-${second}`] = 'captured';
  }
  await page.goto('http://localhost:3002');
  await page.keyboard.press('Enter');
  await page.waitForTimeout(150);
  results.keyboardStarted = await page.evaluate(() => eval('state'));
  const beforeMove = await page.evaluate(() => eval('p1.x'));
  await page.keyboard.down('d');
  await page.waitForTimeout(250);
  await page.keyboard.up('d');
  results.keyboardMove = { before: beforeMove, after: await page.evaluate(() => eval('p1.x')) };
  await page.keyboard.down('j');
  results.keyboardAttack = await page.evaluate(() => ({ type: eval('p1.attackType'), active: eval('p1.attack') > 0 }));
  await page.keyboard.up('j');
  await page.keyboard.press('p');
  results.keyboardPause = await page.evaluate(() => eval('state'));
  await page.keyboard.press('Escape');
  results.keyboardResume = await page.evaluate(() => eval('state'));
  await page.setViewportSize({ width: 390, height: 844 });
  results.mobileControlsDisplay = await page.locator('.touch-controls').evaluate(element => getComputedStyle(element).display);
  results.mobileButtonSizes = await page.locator('.touch-btn').evaluateAll(buttons => buttons.map(button => ({label:button.getAttribute('aria-label'), width:button.getBoundingClientRect().width, height:button.getBoundingClientRect().height})));
  const right = page.getByRole('button', { name: 'Move right' });
  const box = await right.boundingBox();
  await page.mouse.move(box.x + box.width/2, box.y + box.height/2);
  await page.mouse.down();
  results.touchHeldState = { class: await right.getAttribute('class'), key: await page.evaluate(() => eval('touch.right')) };
  const beforeTouchMove = await page.evaluate(() => eval('p1.x'));
  await page.waitForTimeout(250);
  await page.mouse.up();
  results.touchMove = { before: beforeTouchMove, after: await page.evaluate(() => eval('p1.x')), released: await page.evaluate(() => eval('touch.right')) };
  const pause = page.getByRole('button', { name: 'Pause or resume' });
  await pause.click();
  results.touchPause = await page.evaluate(() => eval('state'));
  await pause.click();
  results.touchResume = await page.evaluate(() => eval('state'));
  await page.screenshot({ path: '/tmp/opencode/rift-mobile.png' });
  return results;
}

